@@ -0,0 +1,33 @@
+//! Quest eligibility projected from explicitly supplied simulator state.
+
+use super::helpers::{ensure_namespace, validate_supplied_relation_id};
+use crate::lua_api::methods::borrow_state;
+use crate::lua_bridge::{stack_val, table_set_rust_fn_static};
+use rilua::vm::state::LuaState;
+use rilua::{LuaResult, Val};
+
+pub(super) fn register(state: &mut LuaState) -> LuaResult<()> {
+    let namespace = ensure_namespace(state, "C_QuestLog")?;
+    table_set_rust_fn_static(
+        state,
+        namespace,
+        "QuestCanHaveWarModeBonus",
+        quest_can_have_war_mode_bonus,
+    )
+}
+
+fn quest_can_have_war_mode_bonus(state: &mut LuaState) -> LuaResult<u32> {
+    let value = stack_val(state, 1);
+    #[cfg(feature = "retail-12-1-0")]
+    let value = rilua::table_security::unwrap_secret(state, value)?;
+    let quest_id = validate_supplied_relation_id(
+        value,
+        "C_QuestLog.QuestCanHaveWarModeBonus: questID must be a number",
+    )?;
+    let eligible = {
+        let sim = borrow_state(state)?;
+        quest_id.is_some_and(|id| sim.quest_war_mode_eligibility.contains(&id))
+    };
+    state.push(Val::Bool(eligible));
+    Ok(1)
+}
diff --git a/src/c_api/helpers.rs b/src/c_api/helpers.rs
index 55bc3ac8c..8944d18f3 100644
--- a/src/c_api/helpers.rs
+++ b/src/c_api/helpers.rs
@@ -5,0 +6,13 @@ use rilua::{LuaResult, Val};
+/// Reject nonnumeric inputs; unrepresented numeric identities cannot match supplied rows.
+pub(crate) fn validate_supplied_relation_id(
+    value: Val,
+    error_message: &'static str,
+) -> LuaResult<Option<i32>> {
+    let Val::Num(number) = value else {
+        return Err(rilua::runtime_error(error_message));
+    };
+    let in_range = (f64::from(i32::MIN)..=f64::from(i32::MAX)).contains(&number);
+    let represented = number.is_finite() && number.fract() == 0.0 && in_range;
+    Ok(represented.then(|| number as i32))
+}
+
